// Literal port of the team's Casa3DSDK (module lights/decor). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installLightsDecor(K: Kernel, shared: Shared): void {
  const { EPS, OPEN_AREA, SEED, Y0, cursor, rngString, roomAt, stairFootprint } = K;
  const lightItem = (...a: any[]): any => K.lightItem(...a);
  // ===== extra lamps by class and seed: table lamp on a bedside table, floor lamp beside the sofa, sconces beside the mirror and an outdoor lamp at the entrance door =====
  function decorLights(api) {
    const R = shared.ctx.r, T = shared.ctx.types, structure = R.style, chance = structure === 'budget' ? 0.35 : structure === 'mid' ? 0.75 : 1, rnd = rngString(SEED() + '|decorluz');
    const itemsF = f => R.items.filter(m => (m.outdoor ? -1 : m.floor) === f && m.type !== 'stairs');
    const rectsF = f => itemsF(f).filter(m => (m.h || 0) > 0.3 && !/rug|floor|concrete|dirt|lawn|ceiling_light|curtain|blinds|picture|mirror|pendant|chandelier|spot/.test(m.type)).map(m => stairFootprint(m));
    const free = (f, x, z, margin) => { // point with no wall or furniture within a radius
      if (!roomAt(f, x, z)) return false;
      for (const c of shared.ctx.colliders) if ((c.f === f) && x > c.x0 - margin && x < c.x1 + margin && z > c.z0 - margin && z < c.z1 + margin) return false;
      for (const r of rectsF(f)) if (x > r[0] - margin && x < r[2] + margin && z > r[1] - margin && z < r[3] + margin) return false;
      return true;
    };
    const puts = (f, type, m0, extra) => {
      const ent = T[type]; if (!ent) return; const com = shared.ctx.roomById[m0.room], g = 'f' + f, base = Y0(f);
      const M = Object.assign({ x: m0.x, z: m0.z, ry: m0.ry || 0, w: m0.w || 0.3, d: m0.d || 0.3, h: m0.h || 0.3, y: 0, base, floor: f, colors: shared.ctx.colors, seed: m0.id, room: m0.room, typeWith: com ? com.type : null, ceiling: com ? com.ceiling : 2.8, on: shared.ctx.night, light: shared.ctx.night, lit: shared.ctx.night }, extra || {});
      cursor.group = g; lightItem({ id: m0.id, room: m0.room }, M, ent, api, g);
    };
    for (const c of R.rooms) {
      if (c.type === 'void' || OPEN_AREA(c)) continue; const f = c.floor, mv = R.items.filter(m => m.room === c.id && !m.outdoor);
      if (structure === 'commercial') continue;
      // table lamp on a bedside table / low chest (bedroom, living room)
      if (/bedroom|suite|living/.test(c.type)) for (const m of mv) if (/^(nightstand|dresser|console_table)$/.test(m.type) && (m.h || 1) <= 0.8 && rnd() < chance && !mv.some(o => o !== m && (o.y || 0) > 0.3 && Math.abs(o.x - m.x) < 0.3 && Math.abs(o.z - m.z) < 0.3)) { puts(f, 'table_lamp', { id: 'ab_' + m.id, room: c.id, x: m.x, z: m.z, ry: m.ry }, { y: m.h || 0.6 }); break; }
      // floor lamp beside the sofa
      if (c.type === 'living' && structure !== 'budget' && rnd() < 0.7) { const sf = mv.find(m => /^sofa/.test(m.type)); if (sf) { const co = Math.cos(sf.ry || 0), si = Math.sin(sf.ry || 0); for (const sd of (rnd() < 0.5 ? [1, -1] : [-1, 1])) { const lx = sd * (sf.w / 2 + 0.3), lz = -sf.d / 2 + 0.25, x = sf.x + lx * co + lz * si, z = sf.z - lx * si + lz * co; if (free(f, x, z, 0.32)) { puts(f, 'floor_lamp', { id: 'lp_' + sf.id, room: c.id, x, z, ry: 0 }, { h: 1.5 }); break; } } } }
      // sconces on both sides of the mirror (bathroom, powder room)
      if (/bathroom|vanity/.test(c.type) && structure !== 'budget') { const es = mv.find(m => m.type === 'mirror'); if (es && rnd() < 0.8) for (const sd of [-1, 1]) { const co = Math.cos(es.ry || 0), si = Math.sin(es.ry || 0), lx = sd * ((es.w || 0.6) / 2 + 0.2), x = es.x + lx * co, z = es.z - lx * si; puts(f, 'sconce', { id: 'ar' + sd + '_' + es.id, room: c.id, x, z, ry: es.ry || 0 }, { y: (es.y || 0.9) + (es.h || 1.2) * 0.75 + 0.1 }); } }
    }
    // lamp on the outside wall, beside the entrance door
    const pe = R.doors.find(p => p.exterior && p.side === 'front') || R.doors.find(p => p.exterior);
    if (pe && T.outdoor_lamp) {
      const alongU = pe.axis === 'u', wref = R.walls.find(w => w.floor === pe.floor && w.axis === pe.axis && Math.abs((alongU ? w.v0 : w.u0) - pe.pos) < EPS), th = wref ? wref.thickness || 0.15 : 0.15, n = pe.b === 'outside' ? 1 : -1; // n: direction of the outside relative to pe.a
      const inside = roomAt(pe.floor, alongU ? pe.at : pe.pos - 0.4, alongU ? pe.pos - 0.4 : pe.at), sd = inside ? 1 : -1; // outside = opposite the room
      const sdf = roomAt(pe.floor, alongU ? pe.at : pe.pos + 0.4, alongU ? pe.pos + 0.4 : pe.at) ? -1 : 1;
      const u = pe.at + pe.width / 2 + 0.32, face = pe.pos + sdf * th / 2, ry = alongU ? (sdf > 0 ? 0 : Math.PI) : (sdf > 0 ? K.PE : -K.PE);
      puts(pe.floor, 'outdoor_lamp', { id: 'ext_' + pe.id, room: 'outside', x: alongU ? u : face, z: alongU ? face : u, ry }, { y: Y0(pe.floor) + 2.15 - Y0(pe.floor) });
      void n; void sd;
    }
  }
  Object.assign(K, { decorLights });
}
